from .factory import Factory


class OpticalSwitch:
    def setup_optical_switch(self, optical_switch, **kwargs):
        optical_switch_device = Factory.create(optical_switch, **kwargs)
        return optical_switch_device

    def get_channels(self, optical_switch_device):
        return optical_switch_device.get_optical_switch_channels()

    def get_connection_details(self, connection, optical_switch_device):
        return optical_switch_device.get_optical_switch_connection_details(connection)

    def remove_connections(self, in_ports, out_ports, optical_switch_device, **kwargs):
        return optical_switch_device.remove_connections(in_ports=in_ports, out_ports=out_ports, **kwargs)

    def remove_all_connections(self, optical_switch_device):
        return optical_switch_device.remove_all_connections()

    def set_channels(self, settings, optical_switch_device):
        optical_switch_device.set_optical_switch_channels(settings)

    def set_channel(self, settings, optical_switch_device):
        optical_switch_device.set_optical_switch_channel(settings)

    def activate_connection(self, connection, optical_switch_device):
        optical_switch_device.activate_connection(connection)

    def deactivate_connection(self, connection, optical_switch_device):
        optical_switch_device.deactivate_connection(connection)

    def set_link_flapping(
        self,
        ports,
        optical_switch_device,
        lowperiod=None,
        highperiod=None,
        repeat=None,
        duration=None,
        period=None,
        frequency=None,
    ):
        optical_switch_device.set_link_flapping(
            lowperiod=lowperiod,
            highperiod=highperiod,
            period=period,
            frequency=frequency,
            repeat=repeat,
            duration=duration,
            ports=ports,
        )

    def set_multiple_cross_connections(self, connection_list, optical_switch_device):
        optical_switch_device.set_multiple_cross_connections(connection_list)

    def dropout(self, port, duration, optical_switch_device):
        optical_switch_device.dropout(port, duration)

    def teardown(self, device):
        device.teardown()
